    ∃ j i u v p, u ∈ Q j ∧ v ∈ W j i ∧ p ∈ P i ∧ (u ++ v) ++ p = w

lemma mem_finish_iff {W : S → S → Language Alphabet} {Q : S → Language Alphabet}
